?>
<!doctype html><html lang="<?php echo snap_escape_attr($view['site']['language']); ?>" dir="<?php echo snap_escape_attr($view['site']['direction']); ?>">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo snap_escape_html($view['response']['page_title'] ?? $view['site']['site_name']); ?></title><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['base_style_url'] ?? ''); ?>"><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['skin_style_url']); ?>"><?php if (!empty($view['site']['skin_variant_url'])): ?><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['skin_variant_url']); ?>"><?php endif; ?><?php echo snap_render_html($view['site']['skin_custom_style'] ?? ''); ?><?php echo snap_render_html($view['site']['skin_presentation']['style'] ?? ''); ?></head>
<body class="impact-printer-v2" data-archive-layout="<?php echo $archiveIsMasonry ? 'masonry' : 'thumbs'; ?>"><div id="page-wrapper"><div id="scroll-stage">
<header id="ip-header" class="site-header" data-sticky-header><div class="ip-header-inside"><a class="site-title logo-area" href="<?php echo snap_route_url('home'); ?>"><span class="site-title-text"><?php echo snap_escape_html($view['site']['site_name']); ?></span></a><?php echo snap_render_html(snap_render_component('navigation', ['items' => $view['response']['navigation'] ?? []])); ?></div></header>
<?php if ($archiveIsMasonry): ?>
<main id="justified-grid" class="ss-scroll-wall archive-layout-masonry"><?php foreach (($view['response']['items'] ?? []) as $item): ?><?php echo snap_render_html(snap_render_component('wall-tile', ['item' => $item])); ?><?php endforeach; ?></main><?php if (!empty($view['response']['next_page'])): ?><div class="scroll-wall-sentinel" data-next="<?php echo snap_escape_attr($view['response']['next_page']); ?>" data-has-more="1" aria-hidden="true"></div><?php endif; ?>
<?php else: ?>
<main id="browse-grid" class="<?php echo snap_escape_attr($archiveThumbStyle); ?>-grid archive-grid archive-layout-<?php echo snap_escape_attr($archiveThumbStyle); ?>"><?php foreach (($view['response']['items'] ?? []) as $item): ?><?php $orientation = (int)($item['img_orientation'] ?? 0); $orientationClass = $orientation === 1 ? 'orient-portrait' : ($orientation === 2 ? 'orient-square' : 'orient-landscape'); $thumb = $archiveThumbStyle === 'square' ? ($item['img_thumb_square'] ?? $item['img_thumb_aspect'] ?? $item['img_file'] ?? '') : ($item['img_thumb_aspect'] ?? $item['img_thumb_square'] ?? $item['img_file'] ?? ''); ?><article class="thumb-container h-entry"><a class="thumb-link <?php echo snap_escape_attr($orientationClass); ?>" href="<?php echo snap_escape_url($item['url'] ?? snap_route_url('photo',['slug'=>$item['img_slug'] ?? ''])); ?>" title="<?php echo snap_escape_attr($item['img_title'] ?? $item['title'] ?? ''); ?>"><?php if ($thumb !== ''): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$thumb,'alt'=>$item['img_alt'] ?? $item['img_title'] ?? ''])); ?><?php endif; ?></a></article><?php endforeach; ?></main>
<?php endif; ?>
<footer id="system-footer" class="site-footer<?php if (!empty($view['site']['footer']['lowercase'])): ?> footer-lowercase<?php endif; ?>"><div class="inside"><?php echo snap_render_html(snap_render_component('footer', ['footer' => $view['site']['footer'] ?? []])); ?></div></footer></div></div><?php echo snap_render_html(snap_render_component('registered-assets',['assets'=>$view['site']['registered_assets'] ?? []])); ?><?php echo snap_render_html($view['site']['owner_custom_code'] ?? ''); ?></body></html>
<?php else: ?><?php echo snap_render_html(snap_render_component('impact-printer-page', $view)); ?><?php endif; ?>
